using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
namespace PowerShapeMcp;
[McpServerToolType]
public sealed class OwnedCurveRotationTools(BridgeSession session){
 [McpServerTool(Name="execute_owned_curve_rotation",ReadOnly=false,Destructive=true,Idempotent=false,OpenWorld=false)]
 [Description("Execute one owned COMPCURVE signed90/180 rotation around principal WORLD X/Y/Z and explicit bounded pivot among one unchanged neighboring SOLID, using the original disabled rotate_entities plan and shared native one-call claim/fence/journal lifecycle. Requires raw mm/factor1, idle empty WORLD, complete explicit1..N controls,N2..32. Positions and both tangent directions rotate; magnitudes/free flags and SOLID face witnesses remain unchanged. Fenced until separate verification. No selection/save/OPEN/close/inverse/replay. Control/sample proof only, not full topology. Full only; separate default-off flag.")]
 public Task<CallToolResult> Execute([Description("Fresh unconsumed ownedRotationHandle for the original one-curve signed90/180 principal-axis plan and owned binding in this connection.")]string ownedRotationHandle,[Description("Exact complete startIndex1,endIndexN,N2..32; independently checked against POINT.NUMBER.")]JsonElement curveRange,CancellationToken cancellationToken)=>new ExecutionTools(session).Run("execute_owned_curve_rotation",new(){["ownedRotationHandle"]=ownedRotationHandle,["curveRange"]=JsonNode.Parse(curveRange.GetRawText())},cancellationToken);
 [McpServerTool(Name="verify_owned_curve_rotation",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
 [Description("Independently verify the original COMPCURVE declared principal-axis execution using its raw receipt, original rotation plan, one-use claim, journal and fresh candidate/listing/control/SOLID witnesses. May complete original journal and release only matching fence; no CAD command, selection, save, inverse or replay. Full only.")]
 public Task<CallToolResult> Verify([Description("Original native execution request ID.")]string executionRequestId,[Description("Original raw execution receipt SHA256,64 lowercasehex.")]string executionReceiptSha256,[Description("Fresh post-return candidate document.")]string candidateDocumentHandle,[Description("Fresh one-use active document listing choice.")]string activeDocumentHandle,CancellationToken cancellationToken)=>new ExecutionTools(session).Run("verify_owned_curve_rotation",new(){["executionRequestId"]=executionRequestId,["executionReceiptSha256"]=executionReceiptSha256,["candidateDocumentHandle"]=candidateDocumentHandle,["activeDocumentHandle"]=activeDocumentHandle},cancellationToken);
 public static McpServerTool[] Create(BridgeSession s){if(!s.ExecutionEnabled("execute_owned_curve_rotation"))return[];var t=new OwnedCurveRotationTools(s);var schema=SolidQuarterTurnTools.Schema("ownedRotationHandle");schema["properties"]!["ownedRotationHandle"]!["description"]="Original unconsumed one-curve ownedRotationHandle in this connection.";schema["properties"]!["curveRange"]=new JsonObject{["type"]="object",["description"]="Complete explicit1..N controls, N2..32; verified against native POINT.NUMBER.",["properties"]=new JsonObject{["startIndex"]=new JsonObject{["type"]="integer",["const"]=1},["endIndex"]=new JsonObject{["type"]="integer",["minimum"]=2,["maximum"]=32}},["required"]=new JsonArray("startIndex","endIndex"),["additionalProperties"]=false};schema["required"]!.AsArray().Add("curveRange");return[new StrictTool(McpServerTool.Create(t.Execute),s,schema,x=>CurveTranslationProof.Range(x["curveRange"]!.AsObject())),new StrictTool(McpServerTool.Create(t.Verify),s,SolidQuarterTurnTools.Schema("executionRequestId","executionReceiptSha256","candidateDocumentHandle","activeDocumentHandle"))];}
